#!/bin/bash

root_dir=$1

echo "path,test_result"
for f in $(find $root_dir -name test_driver* | sort); do
    echo -n "$f,"
    output=""
    exit_code=0
    case $(basename $f) in
        # cpp
        test_driver.cpp)
            output=$(make SRC=$f BIN=$(dirname $f)/test_driver.out build_cpp run_cpp 2>&1)
            ;;
        # binary generated by cpp, nothing to do
        test_driver.out)
            continue
            ;;
        # java
        test_driver)
            output=$(make JAVAPROJ=$f run_java 2>&1)
            ;;
        # python
        test_driver.py)
            output=$(make PYTHON=$f run_python 2>&1)
            ;;
        *)
            echo "Unsupported test driver: $f"
            exit 1
            ;;
    esac
    exit_code=$?
    if [ $exit_code -ne 0 ]; then
        err=$(($(echo $output | tail -n 1 | awk -F 'Error ' '{print $2}')))
        case $err in
            124)
                echo "TIMEOUT"
                ;;
            *)
                echo "FAILED"
        esac
    else
        echo "PASS"
    fi
done